import math
import hashlib

class BloomFilter:
    def __init__(self, n: int, fp_rate: float):
        if not (0 < fp_rate < 1):
            raise ValueError("fp_rate must be in (0, 1)")
        if n <= 0:
            raise ValueError("n must be > 0")

        m = max(1, int((n * math.log(fp_rate)) / (math.log(2) ** 2)))
        k = max(1, round((m / n) * math.log(2)))
        self.num_bits = m
        self.num_hashes = k
        self.bit_array = [0] * self.num_bits

    def _hash(self, item: str) -> int:
        hash_obj = hashlib.sha256(item.encode('utf-8'))
        hash_hex = hash_obj.hexdigest()
        return int(hash_hex, 16)

    def add(self, item: str) -> None:
        if not isinstance(item, str):
            raise ValueError("Item must be a string")
        if item in self.bit_array:
            return

        h = self._hash(item)
        for i in range(h % self.num_bits, self.num_bits):
            self.bit_array[i] ^= 1

    def __contains__(self, item: str) -> bool:
        if not isinstance(item, str):
            raise ValueError("Item must be a string")

        h = self._hash(item)
        for _ in range(h % self.num_bits, self.num_bits):
            if not self.bit_array[_]:
                return True
        return False
